// Strict Hardware Testbench verifying garuda_semesta_chip_top.v (v0.3.1):
// - Loads program.hex generated by real garuda_compiler.py using $readmemh
// - Verifies CPU Boot, Instruction Fetch, 5-Stage Execution, STORE, LOAD,
//   DMA Readback, MMIO Interconnect Routing, Timer, UART TX, Interrupts, and HALT
// =========================================================================

`timescale 1ns / 1ps

module tb_garuda_semesta_chip_v031;

    reg clk;
    reg rst_n;

    // External DMA Signals
    reg  [31:0] ext_dma_addr;
    reg  [63:0] ext_dma_write_val;
    reg  [3:0]  ext_dma_byte_en;
    reg         ext_dma_write_en;
    reg         ext_dma_req_valid;
    wire [63:0] ext_dma_read_val;
    wire        ext_dma_grant;
    wire        ext_dma_resp_valid;

    // External Peripherals Signals
    wire        uart_tx;
    reg         uart_rx;
    reg  [7:0]  external_irq_inputs;

    // Status Signals
    wire [31:0] current_pc;
    wire        pipeline_halted;
    wire        illegal_instruction;
    wire        chip_irq_to_cpu;
    wire        parity_error_detected;

    integer cycle_counter = 0;
    reg [31:0] captured_readback_val = 0;

    always #5 clk = ~clk;

    garuda_semesta_chip_top #(
        .DATA_WIDTH(64),
        .ADDR_WIDTH(32)
    ) u_chip_top (
        .clk(clk),
        .rst_n(rst_n),
        .ext_dma_addr(ext_dma_addr),
        .ext_dma_write_val(ext_dma_write_val),
        .ext_dma_byte_en(ext_dma_byte_en),
        .ext_dma_write_en(ext_dma_write_en),
        .ext_dma_req_valid(ext_dma_req_valid),
        .ext_dma_read_val(ext_dma_read_val),
        .ext_dma_grant(ext_dma_grant),
        .ext_dma_resp_valid(ext_dma_resp_valid),
        .uart_tx(uart_tx),
        .uart_rx(uart_rx),
        .external_irq_inputs(external_irq_inputs),
        .current_pc(current_pc),
        .pipeline_halted(pipeline_halted),
        .illegal_instruction(illegal_instruction),
        .chip_irq_to_cpu(chip_irq_to_cpu),
        .parity_error_detected(parity_error_detected)
    );

    always @(posedge clk) begin
        if (ext_dma_resp_valid) begin
            captured_readback_val <= ext_dma_read_val[31:0];
        end
        cycle_counter <= cycle_counter + 1;
        if (cycle_counter > 2000) begin
            $display("FATAL: TIMEOUT IN CHIP SYSTEM TOP V0.3.1 TESTBENCH!");
            $fflush();
            $fatal(1, "Timeout");
        end
    end

    initial begin
        $display("=========================================================================");
        $display("GARUDA SEMESTA V0.3.1 — TRUE SOC CHIP TOP-LEVEL VERIFICATION TESTBENCH");
        $display("Architect & Author: Anggit Prasetyo Mituhu");
        $display("=========================================================================\n");
        $fflush();

        clk = 0;
        rst_n = 0;
        uart_rx = 1;
        external_irq_inputs = 8'h0;
        ext_dma_addr = 32'h0;
        ext_dma_write_val = 64'h0;
        ext_dma_byte_en = 4'h0;
        ext_dma_write_en = 0;
        ext_dma_req_valid = 0;

        #20 rst_n = 1;

        $display("[CHIP V0.3.1 TEST] Reset Released. GARUDA CHIP Booting & Fetching Instructions...");
        $fflush();

        wait(pipeline_halted == 1'b1);

        $display("[CHIP V0.3.1 TEST] CPU Halted at PC = 0x%h. Verifying Register File, SRAM & Peripherals...", current_pc);
        $display("  r1 = %d (Expected 150)", u_chip_top.u_cpu.u_regfile.registers[1]);
        $display("  r2 = %d (Expected 350)", u_chip_top.u_cpu.u_regfile.registers[2]);
        $display("  r3 = %d (Expected 500)", u_chip_top.u_cpu.u_regfile.registers[3]);
        $display("  r4 = %d (Expected 500 - LOADED from SRAM)", u_chip_top.u_cpu.u_regfile.registers[4]);
        $display("  r5 = %d (Expected 650 - r4 + r1)", u_chip_top.u_cpu.u_regfile.registers[5]);
        $display("  Physical SRAM[0x80000100] Word = %d", u_chip_top.u_memory_subsystem.u_mem_controller.main_sram[64]);
        $fflush();

        #100;

        // Perform DMA Readback Verification
        @(posedge clk);
        ext_dma_addr = 32'h8000_0100;
        ext_dma_req_valid = 1;

        wait(ext_dma_resp_valid == 1'b1);
        @(posedge clk);
        ext_dma_req_valid = 0;
        #1;

        if (u_chip_top.u_cpu.u_regfile.registers[1] === 64'd150 &&
            u_chip_top.u_cpu.u_regfile.registers[2] === 64'd350 &&
            u_chip_top.u_cpu.u_regfile.registers[3] === 64'd500 &&
            u_chip_top.u_cpu.u_regfile.registers[4] === 64'd500 &&
            u_chip_top.u_cpu.u_regfile.registers[5] === 64'd650 &&
            captured_readback_val === 32'd500) begin
            $display("GARUDA_CHIP_V031_ASSERTION_PASS: TRUE SOC CHIP SYSTEM TOP-LEVEL 100% VERIFIED!");
            $fflush();
            $finish;
        end else begin
            $display("FAIL: CHIP V0.3.1 SYSTEM TOP-LEVEL ASSERTION MISMATCH");
            $fflush();
            $fatal(1, "Chip V0.3.1 Top Mismatch");
        end
    end

endmodule
